import { expect, sample, test, uniqueName } from "../../fixtures";

// Assumption: the insurance certificate's expiry date is read from the uploaded
// document's text during extraction, so we embed the target expiry date in the file.

const isoDateInDays = (days: number): string => {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
};

const FLAG = "insurance_expiring_soon";

const cases = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
] as const;

for (const { days, include } of cases) {
  test(
    `insurance expiring in ${days} days ${include ? "flags" : "does not flag"} the vendor`,
    { tag: "@REV-08" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const name = uniqueName("Insurance Expiry");

      const createResponse = await member.post("/api/vendors", {
        data: {
          name,
          category: "services",
          contact_email: `ops+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const expiry = isoDateInDays(days);
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance.txt",
            mimeType: "text/plain",
            buffer: Buffer.from(`Certificate of Insurance\nExpiry Date: ${expiry}\n`),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      // Wait for extraction to finish before reading the flags.
      await expect
        .poll(
          async () => {
            const r = await member.get(`/api/documents/${document.id}`);
            return ((await r.json()) as { status: string }).status;
          },
          { timeout: 60_000 },
        )
        .not.toBe("processing");

      // Act
      const response = await member.get(`/api/vendors/${vendor.id}`);

      // Assert
      expect(response.status()).toBe(200);
      const body = await response.json();
      if (include) {
        expect(body.flags).toContain(FLAG);
      } else {
        expect(body.flags).not.toContain(FLAG);
      }
    },
  );
}
